121	export class WikiEquipmentEnricher {
122	    private static instance: WikiEquipmentEnricher;
123	
124	    private readonly API_BASE = 'https://runescape.wiki/api.php';
125	    private readonly USER_AGENT = 'POG2-Sovereign/1.0 (Sovereign Research Node; respectful-soft-parse)';
126	    private readonly RATE_LIMIT_MS = 1500;
127	    private readonly CACHE_DIR: string;
128	    private readonly CACHE_TTL_MS = 7 * 24 * 60 * 60 * 1000; // 7 days
129	
130	    private lastRequestTime = 0;
131	    private requestCount = 0;
132	
133	    private constructor() {
134	        this.CACHE_DIR = join('D:', 'sovereign', 'atlas', 'wiki', 'cache');
135	        this.ensureCacheDir();
136	    }
137	
138	    public static getInstance(): WikiEquipmentEnricher {
139	        if (!this.instance) {
140	            this.instance = new WikiEquipmentEnricher();
141	        }
142	        return this.instance;
143	    }
144	
145	    // ── Cache Layer ────────────────────────────────────────
146	
147	    private ensureCacheDir(): void {
148	        const dirs = [
149	            this.CACHE_DIR,
150	            join(this.CACHE_DIR, 'items'),
151	            join(this.CACHE_DIR, 'monsters'),
152	            join(this.CACHE_DIR, 'templates'),
153	            join(this.CACHE_DIR, 'wikitext'),
154	            join(this.CACHE_DIR, 'generic')
155	        ];
156	        for (const dir of dirs) {
157	            if (!existsSync(dir)) {
158	                mkdirSync(dir, { recursive: true });
159	            }
160	        }
161	    }
162	
163	    private sanitizeFilename(name: string): string {
164	        return name.replace(/[<>:"/\\|?*]/g, '_').replace(/\s+/g, '_').toLowerCase();
165	    }
166	
167	    private readCache(subdir: string, key: string): any | null {
168	        const filePath = join(this.CACHE_DIR, subdir, `${this.sanitizeFilename(key)}.json`);
169	        if (!existsSync(filePath)) return null;
170	
171	        try {
172	            const raw = readFileSync(filePath, 'utf8');
173	            const cached = JSON.parse(raw);
174	
175	            // TTL check
176	            if (cached._cachedAt && (Date.now() - cached._cachedAt) > this.CACHE_TTL_MS) {
177	                logger.debug({ key }, 'Cache expired, will re-fetch.');
178	                return null;
179	            }
180	
181	            return cached;
182	        } catch {
183	            return null;
184	        }
185	    }
186	
187	    private writeCache(subdir: string, key: string, data: any): void {
188	        const filePath = join(this.CACHE_DIR, subdir, `${this.sanitizeFilename(key)}.json`);
189	        try {
190	            writeFileSync(filePath, JSON.stringify({ ...data, _cachedAt: Date.now() }, null, 2), 'utf8');
191	        } catch (err) {
192	            logger.warn({ key, err }, 'Failed to write cache.');
193	        }
194	    }
195	
196	    // ── Rate Limiter ───────────────────────────────────────
197	
198	    private async throttle(): Promise<void> {
199	        const now = Date.now();
200	        const elapsed = now - this.lastRequestTime;
201	        if (elapsed < this.RATE_LIMIT_MS) {
202	            const delay = this.RATE_LIMIT_MS - elapsed;
203	            await new Promise(resolve => setTimeout(resolve, delay));
204	        }
205	        this.lastRequestTime = Date.now();
206	        this.requestCount++;
207	    }
208	
209	    // ── API Layer ──────────────────────────────────────────
210	
211	    /**
212	     * Fetch raw wikitext for a page. Checks disk cache first.
213	     */
214	    private async fetchWikitext(pageTitle: string): Promise<string | null> {
215	        const cached = this.readCache('wikitext', pageTitle);
216	        if (cached?.wikitext) {
217	            logger.debug({ title: pageTitle }, 'Wikitext served from cache.');
218	            return cached.wikitext;
219	        }
220	
221	        await this.throttle();
222	
223	        const params = new URLSearchParams({
224	            action: 'parse',
225	            format: 'json',
226	            page: pageTitle,
227	            prop: 'wikitext',
228	            origin: '*'
229	        });
230	
231	        try {
232	            const response = await fetch(`${this.API_BASE}?${params.toString()}`, {
233	                headers: {
234	                    'User-Agent': this.USER_AGENT,
235	                    'Accept': 'application/json'
236	                },
237	                signal: AbortSignal.timeout(10000)
238	            });
239	
240	            if (!response.ok) {
241	                logger.warn({ title: pageTitle, status: response.status }, 'Wiki API non-OK response.');
242	                return null;
243	            }
244	
245	            const data = await response.json() as any;
246	            const wikitext = data.parse?.wikitext?.['*'] || null;
247	
248	            if (wikitext) {
249	                this.writeCache('wikitext', pageTitle, { wikitext });
250	                logger.info({ title: pageTitle, length: wikitext.length, request: this.requestCount }, 'Wikitext fetched.');
251	            }
252	
253	            return wikitext;
254	        } catch (err) {
255	            logger.error({ title: pageTitle, err }, 'Failed to fetch wikitext.');
256	            return null;
257	        }
258	    }
259	
260	    /**
261	     * Search for the canonical page title matching a query.
262	     */
263	    private async searchPage(query: string): Promise<string | null> {
264	        await this.throttle();
265	
266	        const params = new URLSearchParams({
267	            action: 'query',
268	            format: 'json',
269	            list: 'search',
270	            srsearch: query,
271	            srlimit: '1',
272	            origin: '*'
273	        });
274	
275	        try {
276	            const response = await fetch(`${this.API_BASE}?${params.toString()}`, {
277	                headers: { 'User-Agent': this.USER_AGENT },
278	                signal: AbortSignal.timeout(10000)
279	            });
280	
281	            const data = await response.json() as any;
282	            return data.query?.search?.[0]?.title || null;
283	        } catch (err) {
284	            logger.error({ query, err }, 'Wiki search failed.');
285	            return null;
286	        }
287	    }
288	
289	    /**
290	     * Resolves a name to wikitext. Tries direct fetch, follows redirects, falls back to search.
291	     */
292	    private async getWikitextForName(name: string): Promise<string | null> {
293	        // Try direct page first
294	        let wikitext = await this.fetchWikitext(name);
295	
296	        // Follow #REDIRECT if the page is a redirect stub
297	        if (wikitext && wikitext.trim().startsWith('#REDIRECT')) {
298	            const redirectMatch = wikitext.match(/\[\[([^\]]+)\]\]/);
299	            if (redirectMatch) {
300	                const redirectTarget = redirectMatch[1].trim();
301	                logger.info({ from: name, to: redirectTarget }, 'Following wiki redirect...');
302	                wikitext = await this.fetchWikitext(redirectTarget);
303	            }
304	        }
305	
306	        if (!wikitext) {
307	            // Fallback: search for the page
308	            const title = await this.searchPage(name);
309	            if (title && title !== name) {
310	                wikitext = await this.fetchWikitext(title);
311	                // Follow redirect on search result too
312	                if (wikitext && wikitext.trim().startsWith('#REDIRECT')) {
313	                    const redirectMatch = wikitext.match(/\[\[([^\]]+)\]\]/);
314	                    if (redirectMatch) {
315	                        const redirectTarget = redirectMatch[1].trim();
316	                        logger.info({ from: title, to: redirectTarget }, 'Following wiki redirect (search fallback)...');
317	                        wikitext = await this.fetchWikitext(redirectTarget);
318	                    }
319	                }
320	            }
321	        }
322	
323	        return wikitext;
324	    }
325	
326	    // ── Template Parser ────────────────────────────────────
327	
328	    /**
329	     * Extract a single template's parameters from wikitext.
330	     * Handles nested templates via bracket-depth tracking.
331	     */
332	    private extractTemplate(wikitext: string, templateName: string): Record<string, string> | null {
333	        const lowerText = wikitext.toLowerCase();
334	        const lowerName = templateName.toLowerCase();
335	
336	        let searchIdx = 0;
337	        let startIdx = -1;
338	
339	        while (searchIdx < lowerText.length) {
340	            const bracePos = lowerText.indexOf('{{', searchIdx);
341	            if (bracePos === -1) break;
342	
343	            let nameStart = bracePos + 2;
344	            while (nameStart < lowerText.length && (lowerText[nameStart] === ' ' || lowerText[nameStart] === '\n')) nameStart++;
345	
346	            if (lowerText.substring(nameStart, nameStart + lowerName.length) === lowerName) {
347	                const afterName = lowerText[nameStart + lowerName.length];
348	                if (afterName === '|' || afterName === '}' || afterName === ' ' || afterName === '\n' || afterName === '\r' || afterName === undefined) {
349	                    startIdx = bracePos;
350	                    break;
351	                }
352	            }
353	            searchIdx = bracePos + 2;
354	        }
355	
356	        if (startIdx === -1) return null;
357	
358	        // Find matching closing }} using bracket depth
359	        let depth = 0;
360	        let endIdx = startIdx;
361	        for (let i = startIdx; i < wikitext.length - 1; i++) {
362	            if (wikitext[i] === '{' && wikitext[i + 1] === '{') {
363	                depth++;
364	                i++;
365	            } else if (wikitext[i] === '}' && wikitext[i + 1] === '}') {
366	                depth--;
367	                i++;
368	                if (depth === 0) {
369	                    endIdx = i + 1;
370	                    break;
371	                }
372	            }
373	        }
374	
375	        if (depth !== 0) return null;
376	
377	        const fullContent = wikitext.substring(startIdx + 2, endIdx - 2);
378	        const pipeIdx = fullContent.indexOf('|');
379	        if (pipeIdx === -1) return {};
380	
381	        return this.parseTemplateParams(fullContent.substring(pipeIdx + 1));
382	    }
383	
384	    /**
385	     * Extract ALL instances of a template from wikitext.
386	     * Critical for DropsLine parsing where each drop is a separate template call.
387	     */
388	    private extractAllTemplateInstances(wikitext: string, templateName: string): Record<string, string>[] {
389	        const results: Record<string, string>[] = [];
390	        const lowerText = wikitext.toLowerCase();
391	        const lowerName = templateName.toLowerCase();
392	        let searchIdx = 0;
393	
394	        while (searchIdx < lowerText.length) {
395	            const bracePos = lowerText.indexOf('{{', searchIdx);
396	            if (bracePos === -1) break;
397	
398	            let nameStart = bracePos + 2;
399	            while (nameStart < lowerText.length && (lowerText[nameStart] === ' ' || lowerText[nameStart] === '\n')) nameStart++;
400	
401	            if (lowerText.substring(nameStart, nameStart + lowerName.length) === lowerName) {
402	                const afterName = lowerText[nameStart + lowerName.length];
403	                if (afterName === '|' || afterName === '}' || afterName === ' ' || afterName === '\n') {
404	                    // Find closing braces
405	                    let depth = 0;
406	                    let endIdx = bracePos;
407	                    for (let i = bracePos; i < wikitext.length - 1; i++) {
408	                        if (wikitext[i] === '{' && wikitext[i + 1] === '{') { depth++; i++; }
409	                        else if (wikitext[i] === '}' && wikitext[i + 1] === '}') {
410	                            depth--; i++;
411	                            if (depth === 0) { endIdx = i + 1; break; }
412	                        }
413	                    }
414	
415	                    const fullContent = wikitext.substring(bracePos + 2, endIdx - 2);
416	                    const pipeIdx = fullContent.indexOf('|');
417	                    if (pipeIdx !== -1) {
418	                        results.push(this.parseTemplateParams(fullContent.substring(pipeIdx + 1)));
419	                    }
420	
421	                    searchIdx = endIdx;
422	                    continue;
423	                }
424	            }
425	            searchIdx = bracePos + 2;
426	        }
427	
428	        return results;
429	    }
430	
431	    /**
432	     * Parse pipe-separated template parameters, respecting nested template depth.
433	     * Handles {{nested|templates}} and [[wiki|links]] inside parameter values.
434	     */
435	    private parseTemplateParams(text: string): Record<string, string> {
436	        const params: Record<string, string> = {};
437	        let depth = 0;
438	        let currentParam = '';
439	        let positionalIdx = 1;
440	
441	        for (let i = 0; i < text.length; i++) {
442	            const ch = text[i];
443	            const next = text[i + 1];
444	
445	            if (ch === '{' && next === '{') { depth++; currentParam += '{{'; i++; }
446	            else if (ch === '}' && next === '}') { depth--; currentParam += '}}'; i++; }
447	            else if (ch === '[' && next === '[') { depth++; currentParam += '[['; i++; }
448	            else if (ch === ']' && next === ']') { depth--; currentParam += ']]'; i++; }
449	            else if (ch === '|' && depth === 0) {
450	                this.assignParam(params, currentParam, positionalIdx);
451	                positionalIdx++;
452	                currentParam = '';
453	            } else {
454	                currentParam += ch;
455	            }
456	        }
457	
458	        // Last parameter
459	        if (currentParam.trim()) {
460	            this.assignParam(params, currentParam, positionalIdx);
461	        }
462	
463	        return params;
464	    }
465	
466	    private assignParam(params: Record<string, string>, raw: string, positionalIdx: number): void {
467	        const eqIdx = raw.indexOf('=');
468	        if (eqIdx > 0 && !raw.substring(0, eqIdx).includes('{{')) {
469	            const key = raw.substring(0, eqIdx).trim().toLowerCase();
470	            const value = this.cleanWikiMarkup(raw.substring(eqIdx + 1).trim());
471	            if (key) params[key] = value;
472	        } else {
473	            params[`_${positionalIdx}`] = this.cleanWikiMarkup(raw.trim());
474	        }
475	    }
476	
477	    /**
478	     * Strip wiki markup from a value (links, formatting, refs).
479	     */
480	    private cleanWikiMarkup(text: string): string {
481	        return text
482	            .replace(/\[\[(?:[^\]|]*\|)?([^\]]*)\]\]/g, '$1')  // [[Link|Text]] -> Text
483	            .replace(/'''?/g, '')                                // Bold/italic
484	            .replace(/<ref[^>]*>.*?<\/ref>/gs, '')               // References
485	            .replace(/<ref[^/]*\/>/g, '')                        // Self-closing refs
486	            .replace(/<br\s*\/?>/gi, ' ')                        // Line breaks
487	            .replace(/<!--.*?-->/gs, '')                         // HTML comments
488	            .replace(/&nbsp;/g, ' ')                             // Non-breaking spaces
489	            .trim();
490	    }
491	
492	    // ── Structured Parsers ─────────────────────────────────
493	
494	    /**
495	     * Parse equipment bonuses from an item's wiki page.
496	     * Tries: Infobox Bonuses, Infobox bonuses, Infobox Bonuses Beta
497	     */
498	    public async parseEquipmentBonuses(itemName: string): Promise<WikiEquipmentBonuses | null> {
499	        const wikitext = await this.getWikitextForName(itemName);
500	        if (!wikitext) return null;
501	
502	        const templateNames = ['Infobox Bonuses', 'Infobox bonuses', 'Infobox Bonuses Beta'];
503	        let bonuses: Record<string, string> | null = null;
504	
505	        for (const name of templateNames) {
506	            bonuses = this.extractTemplate(wikitext, name);
507	            if (bonuses) break;
508	        }
509	
510	        if (!bonuses) return null;
511	
512	        return {
513	            tier: this.safeInt(bonuses['tier'] || bonuses['level'] || '0'),
514	            slot: bonuses['slot'] || 'unknown',
515	            class: bonuses['class'] || bonuses['type'] || 'none',
516	            style: bonuses['style'] || bonuses['astyle'] || 'none',
517	            damage: this.safeInt(bonuses['damage'] || bonuses['dmg'] || '0'),
518	            accuracy: this.safeInt(bonuses['accuracy'] || bonuses['acc'] || '0'),
519	            armour: this.safeInt(bonuses['armour'] || bonuses['armor'] || bonuses['defence'] || '0'),
520	            lifeBonus: this.safeInt(bonuses['life'] || bonuses['lp'] || bonuses['lifepoints'] || '0'),
521	            prayerBonus: this.safeInt(bonuses['prayer'] || '0'),
522	            attackSpeed: bonuses['speed'] || bonuses['aspeed'] || 'average'
523	        };
524	    }
