526	    /**
527	     * Parse item metadata from an item's wiki page.
528	     */
529	    public async parseItemMeta(itemName: string): Promise<WikiItemMeta | null> {
530	        const wikitext = await this.getWikitextForName(itemName);
531	        if (!wikitext) return null;
532	
533	        const info = this.extractTemplate(wikitext, 'Infobox Item')
534	                   || this.extractTemplate(wikitext, 'Infobox item');
535	        if (!info) return null;
536	
537	        return {
538	            name: info['name'] || itemName,
539	            examine: info['examine'] || '',
540	            tradeable: this.safeBool(info['tradeable'] || info['tradable']),
541	            stackable: this.safeBool(info['stackable']),
542	            members: this.safeBool(info['members']),
543	            weight: parseFloat(info['weight'] || '0') || 0,
544	            highAlch: this.safeInt(info['high'] || info['highalch'] || '0'),
545	            lowAlch: this.safeInt(info['low'] || info['lowalch'] || '0'),
546	            // ge field: Grand Exchange mid-price (or ge_sell, exchange, value)
547	            geValue: this.safeInt(info['ge'] || info['exchange'] || info['ge_buy'] || info['value'] || '0'),
548	            quest: info['quest'] || 'No',
549	            release: info['release'] || 'Unknown'
550	        };
551	    }
