578	            // March 2026 Combat Affinities
579	            defence: this.safeInt(info['defence'] || '0'),
580	            armour: this.safeInt(info['armour'] || '0'),
581	            affinityMelee: this.safeInt(info['aff_melee'] || '55'),
582	            affinityRanged: this.safeInt(info['aff_ranged'] || '55'),
583	            affinityMagic: this.safeInt(info['aff_magic'] || '55'),
584	            affinityNecromancy: this.safeInt(info['aff_necromancy'] || '55')
585	        };
