588	    /**
589	     * Parse all drop table entries from a monster's wiki page.
590	     * Includes sub-table resolution (Rare drop table, Gem drop table, etc.)
591	     */
592	    public async parseDropTables(npcName: string): Promise<WikiDropTable[]> {
593	        const wikitext = await this.getWikitextForName(npcName);
594	        if (!wikitext) return [];
