91	  const normalized = bossName.toLowerCase().replace(/[^a-z0-9]/g, '');
92	  
93	  const cached = rotationsCache.get(normalized);
94	  if (cached && Date.now() - cached.timestamp < CACHE_TTL) {
95	    return cached.data;
96	  }
97	
98	  const title = bossName.includes('/') ? bossName : `${bossName}/Strategies`;
99	  
100	  try {
101	    const params = new URLSearchParams({
102	      action: 'parse',
103	      format: 'json',
104	      page: title,
105	      prop: 'wikitext',
106	      origin: '*'
107	    });
108	
109	    const targetUrl = `https://runescape.wiki/api.php?${params.toString()}`;
110	    const data = await proxiedFetch(targetUrl) as { parse?: { wikitext?: { '*': string } } };
111	    const wikitext = data.parse?.wikitext?.['*'] || '';
112	
113	    const rotations: WikiRotation[] = [];
114	    const templateRegex = /\{\{[Aa]bility\s+rotation\s*\|([^}]+)\}\}/g;
115	    let match;
116	
117	    const lines = wikitext.split('\n');
118	    let currentSection = 'General';
119	
120	    for (let i = 0; i < lines.length; i++) {
121	      const line = lines[i];
122	      
123	      if (line.startsWith('==')) {
124	        currentSection = line.replace(/=/g, '').trim();
125	      }
126	
127	      while ((match = templateRegex.exec(line)) !== null) {
128	        const content = match[1];
129	        const abilities = content.split('|')
130	          .map(a => a.trim())
131	          .filter(a => a && !a.includes('=')); 
132	
133	        let label = 'Rotation';
134	        if (i > 0 && lines[i-1].startsWith('!')) {
135	          label = lines[i-1].replace('!', '').trim();
136	        }
137	
138	        rotations.push({
139	          section: currentSection,
140	          label,
141	          abilities: abilities.map(a => {
142	            const predMatch = a.match(/\((if [^)]+)\)/i);
143	            let rawName = a;
144	            let predicate: string | undefined;
145	            if (predMatch) {
146	              predicate = predMatch[1].trim();
147	              rawName = a.replace(predMatch[0], '').trim();
148	            }
149	            return {
150	              name: rawName.replace(/^@/, '').replace(/\[\[File:[^\]]+\]\]/g, '').replace(/&nbsp;/g, ' ').split('|')[0].trim(),
151	              predicate
152	            };
153	          })
154	        });
155	      }
156	    }
157	
158	    if (rotations.length > 0) {
159	      rotationsCache.set(normalized, { data: rotations, timestamp: Date.now() });
160	    }
161	    
162	    return rotations;
163	  } catch (err) {
164	    console.warn(`Wiki rotation fetch failed for "${bossName}":`, err);
165	  }
166	
167	  return [];
168	}
